  }
  if (!requestRefMatch || !isUuid(requestRefMatch[1]) || !isUuid(requestRefMatch[2]) || requestRefMatch[1].toLowerCase() !== publicationId.toLowerCase()) {
    return [{ json: { valid: false, httpStatus: 400, message: 'productStatus requestRef 必须是后端签发的 ozon-readback:<publicationId>:<runId>' } }];
