    .map((value) => String(value || '').trim()).filter(Boolean))];
  if (!offerIds.length || offerIds.length > 100) {
    return [{ json: { valid: false, httpStatus: 400, message: 'productStatus 必须提供 1-100 个 offerId' } }];
  }
  const prefix = readbackRequestRef;
  return [
    { json: { valid: true, action, taskId, storeId: '', publicationId, leaseToken: '', operation: 'infoList', requestRef: prefix + ':infoList', requestId: prefix + ':infoList', payload: { offer_id: offerIds }, request: body } },
    { json: { valid: true, action, taskId, storeId: '', publicationId, leaseToken: '', operation: 'attributesInfo', requestRef: prefix + ':attributesInfo', requestId: prefix + ':attributesInfo', payload: { filter: { offer_id: offerIds }, limit: 100 }, request: body } }
  ];
