const allowedGlobalKeys = action === 'categorySchema'
  ? new Set(['action','storeId','descriptionCategoryId','typeId','locale'])
  : new Set(['action','storeId','payload']);
const unexpectedGlobalKeys = Object.keys(body).filter((key) => !allowedGlobalKeys.has(key));
if (unexpectedGlobalKeys.length || !isUuid(storeId) || taskId || publicationId || leaseToken || !/^\d+$/.test(executionId)) {
