  const structuralValid = requests.length === 2
    && responses.length === 2
    && operationNames.every((operation) => requestGroups[operation].length === 1 && responseGroups[operation].length === 1)
    && operationNames.every((operation) => {
      const expected = requestGroups[operation][0];
      const actual = responseGroups[operation][0];
      return expected.valid === true
        && expected.action === 'productStatus'
        && String(expected.requestId || '') !== ''
        && String(actual.requestId || '') === String(expected.requestId);
    })
    && requestedOfferIds.length >= 1
    && requestedOfferIds.length <= 100
    && requestedOfferIds.every(Boolean)
    && new Set(requestedOfferIds).size === requestedOfferIds.length
    && sameArray(requestedOfferIds, attributeOfferIds);
  const infoResponse = responseGroups.infoList[0] || {};
  const attributesResponse = responseGroups.attributesInfo[0] || {};
