    && infoResult.valid;
  const attributesSuccess = structuralValid
    && attributesResponse.ok === true
    && Number(attributesResponse.statusCode) === 200
    && attributesResult.valid;
  const attributesNotFound = structuralValid
    && attributesResponse.ok === false
    && Number(attributesResponse.statusCode) === 404
    && String(attributesResponse.body?.code) === '5'
    && attributesResponse.body?.message === 'item not found'
    && String(attributesResponse.error?.code) === '5'
