      message: structuralValid ? 'OZON 商品状态只读查询失败' : 'OZON 商品状态只读响应结构无效',
      retryable: structuralValid && failedResponses.length > 0 && failedResponses.every((entry) => entry.retryable === true || entry.error?.retryable === true),
      operations
    } }];
  }
  const infoOperation = {
    operation: 'infoList',
    requestId: String(infoRequest.requestId),
    ok: true,
    upstreamOk: true,
    statusCode: 200,
    outcome: infoResult.items.length ? 'PRESENT' : 'EMPTY',
    resultShape: infoResult.resultShape,
    itemCount: infoResult.items.length
  };
  const attributesOperation = specialAbsence ? {
    operation: 'attributesInfo',
    requestId: String(attributesRequest.requestId),
    ok: true,
    upstreamOk: false,
    statusCode: 404,
    outcome: 'NOT_FOUND',
    resultShape: 'NOT_FOUND_ERROR',
    itemCount: 0,
    errorCode: '5'
  } : {
    operation: 'attributesInfo',
    requestId: String(attributesRequest.requestId),
    ok: true,
    upstreamOk: true,
    statusCode: 200,
    outcome: attributesResult.items.length ? 'PRESENT' : 'EMPTY',
    resultShape: attributesResult.resultShape,
    itemCount: attributesResult.items.length
